// +----------------------------------------------------------------------------
// |"sc_bigint<W>::to_XXXX"
// | 
// | These functions return an object instance's value as the requested
// | native C++ type.
// |
// | Notes: 
// |   (1) These are set up for BITS_PER_DIGIT == 32.
// | Result:
// |     Native C++ type containing the object instance's value.
// +----------------------------------------------------------------------------
inline 
double
to_double() const
{
    return sc_signed_proxy().to_double();
}

inline
int 
to_int() const
{
    int result;

    result =  (int)digit[0];
    return result;
}

inline
unsigned int 
to_uint() const
{
    unsigned int result;

    result =  (unsigned int)digit[0];
    return result;
}

inline
int64 
to_int64() const
{
    int64 result;

    if ( W < 33 ) {
        result =  to_int();
    }
    else {
        result = ( (uint64)digit[1] << BITS_PER_DIGIT ) | digit[0]; 
    }
    return result;
}

inline
uint64 
to_uint64() const
{
    uint64 result;

    if ( W < 33 ) {
        result = to_int();
    }
    else {
        result = to_int64(); // @@@@#### ( (uint64)digit[1] << BITS_PER_DIGIT ) | digit[0];
    }
    return result;
}

inline
long 
to_long() const
{
    long result =  ( sizeof(long) < 5 ) ? to_int() : to_int64();
    return result;
}


inline
unsigned long 
to_ulong() const
{
    unsigned long result = ( sizeof(unsigned long) < 5 ) ? to_uint() : to_uint64();
    return result;
}

