// |     zero = true if the object's digits should be zeroed.
// +----------------------------------------------------------------------------

inline
sc_unsigned::sc_unsigned( int nb, bool zero ) :
    nbits(nb+1), ndigits( DIV_CEIL(nb+1) )
{
    if ( ndigits <= SC_BASE_VEC_DIGITS ) {
        digit = base_vec;
	SC_FREE_DIGIT(false)
    }
    else {
        digit = new sc_digit[ndigits];
	SC_FREE_DIGIT(true)
    }
    if ( zero ) {
        makezero();
    }
}

