#ifndef __TLM_FIFO_RESIZE_H__
#define __TLM_FIFO_RESIZE_H__

/******************************************************************
//
// resize interface
//
******************************************************************/

namespace tlm {

template < typename T>
inline
void
tlm_fifo<T>::nb_expand( unsigned int n ) {

  if( m_size >= 0 ) {
    m_expand = true;
    m_size += n;
    request_update();
  }
}

template < typename T>
inline
void
tlm_fifo<T>::nb_unbound( unsigned int n ) {

  m_expand = true;
  m_size = -n;

  if( buffer.size() < static_cast<int>( n ) ) {
    buffer.resize( n );
  }

  request_update();

}

template < typename T>
inline
bool
tlm_fifo<T>::nb_reduce( unsigned int n ) {

  if( m_size < 0 ) {
    return false;
  }

  return nb_bound( size() - n );

}

template < typename T>
inline
bool
tlm_fifo<T>::nb_bound( unsigned int new_size ) {

  bool ret = true;

  if( static_cast<int>( new_size ) < used() ) {

    new_size = used();
    ret = false;

  }

  m_size = new_size;
  return ret;

}

} // namespace tlm

